function lnrP_saleFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА ПОКУПАТЕЛЯ','<p><b>Автомобиль может быть оформлен непосредственно на покупателя.</b></p><h3>🚘 Как может быть на практике</h3><p>Для непосредственного переоформления требуется личное участие собственника, указанного в свидетельстве о регистрации транспортного средства ЛНР.</p><h3>📋 Что делать</h3><p>Подготовить ДКП в 3 экземплярах, документы сторон и автомобиля, документы о проживании покупателя; представить автомобиль на осмотр. При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>💰 Как безопаснее передать деньги</h3><p>Не рекомендуется полный расчёт до проверки возможности оформления: ДКП → совместное обращение в МРЭО → проверка и принятие документов → окончательный расчёт. Аванс фиксируйте письменно; наличные — распиской; перевод — с понятным назначением платежа.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием.</p>')}
function lnrP_sale(){q('Может ли собственник, указанный в свидетельстве о регистрации транспортного средства ЛНР, лично обратиться вместе с вами в МРЭО?',[['Да, может лично приехать в МРЭО',()=>q('Является ли собственник, указанный в свидетельстве о регистрации транспортного средства ЛНР, гражданином Российской Федерации?',[['Да',()=>lnrP_buyerCitizen(lnrP_saleFinal)],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])],['Нет, не может или не хочет приехать',()=>lnrP_five('Без личного участия собственника непосредственное переоформление на покупателя по сложившейся практике не проводится.')],['Собственник умер',lnrP_deceased],['Собственник неизвестен / связи с ним нет',()=>lnrP_five('При отсутствии связи с собственником практический маршрут — специальная регистрация фактического владельца на 5 лет.')]])}
function lnrP_giftFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА ОДАРЯЕМОГО','<p><b>Основание перехода права собственности — договор дарения.</b></p><h3>🚘 Как может быть на практике</h3><p>Для непосредственного переоформления требуется личное участие дарителя, указанного собственником в свидетельстве о регистрации транспортного средства ЛНР.</p><h3>📋 Что делать</h3><p>Оформить договор дарения, подготовить документы сторон и автомобиля, документы о проживании одаряемого и представить автомобиль на осмотр. При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием.</p>')}
function lnrP_gift(){q('Может ли даритель, указанный собственником в свидетельстве о регистрации транспортного средства ЛНР, лично обратиться вместе с вами в МРЭО?',[['Да, может лично приехать в МРЭО',()=>q('Является ли даритель, указанный собственником в свидетельстве о регистрации транспортного средства ЛНР, гражданином Российской Федерации?',[['Да',()=>lnrP_buyerCitizen(lnrP_giftFinal)],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])],['Нет, не может или не хочет приехать',()=>lnrP_five('Без личного участия дарителя непосредственное переоформление на одаряемого по сложившейся практике не проводится.')],['Даритель умер',lnrP_deceased],['Даритель неизвестен / связи с ним нет',()=>lnrP_five('При отсутствии связи с дарителем практический маршрут — регистрация фактического владельца на 5 лет.')]])}
function lnrP_poa(){q('Может ли собственник, указанный в свидетельстве о регистрации транспортного средства ЛНР, лично приехать в МРЭО?',[['Да',()=>q('Как будет оформлена передача автомобиля?',[['Договор купли-продажи',lnrP_sale],['Договор дарения',lnrP_gift],['Другая ситуация / нет подходящего варианта',()=>other('Л-2Б.1.3')]])],['Нет, не может или не хочет приехать',()=>lnrP_five('По сложившейся практике МРЭО доверенность сама по себе не используется для непосредственного переоформления автомобиля с учёта ЛНР без личного участия зарегистрированного собственника.')],['Собственник умер',lnrP_deceased],['Собственник неизвестен / связи с ним нет',()=>lnrP_five('При отсутствии зарегистрированного собственника практический маршрут — регистрация фактического владельца на 5 лет.')]])}
function lnrP_courtFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ ПО РЕШЕНИЮ СУДА','<p><b>Право собственности подтверждено вступившим в законную силу решением суда РФ.</b></p><p>В этой ветке место проживания в ЛНР не проверяется и личное участие прежнего собственника не требуется.</p><h3>📋 Что подготовить</h3><p>Паспорт РФ, вступившее в законную силу решение суда РФ, имеющиеся регистрационные документы и знаки ЛНР, другие документы на автомобиль; представить автомобиль на осмотр. При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием; далее оцените административное или судебное обжалование.</p>')}
