function lnrP_oral(){q('Может ли собственник, указанный в свидетельстве о регистрации транспортного средства ЛНР, лично обратиться вместе с вами в МРЭО?',[['Да',()=>q('Как фактически автомобиль был передан вам собственником?',[['Я купил автомобиль',lnrP_sale],['Автомобиль был подарен мне',lnrP_gift],['Другая ситуация / нет подходящего варианта',()=>other('Л-2Б.1.5.2')]])],['Нет, не может или не хочет приехать',()=>lnrP_five('Письменная сделка отсутствует. Основание регистрации: объяснение владельца об обстоятельствах, при которых автомобиль поступил в его владение. Указывайте только реальные обстоятельства.')],['Собственник умер',lnrP_deceased],['Собственник неизвестен / связи с ним нет',()=>lnrP_five('Основание регистрации: объяснение владельца об обстоятельствах, при которых автомобиль поступил в его владение. Не оформляйте документы задним числом.')]])}
