function lnrP_ownerBasis(){q('На каком основании автомобиль находится у вас?',[['Договор купли-продажи',lnrP_sale],['Договор дарения',lnrP_gift],['Доверенность',lnrP_poa],['Решение суда РФ о признании права собственности',lnrP_court],['Сделка письменно не оформлялась — автомобиль передан вместе со свидетельством о регистрации транспортного средства ЛНР',lnrP_oral],['Документы о приобретении утрачены',lnrP_lostAcq],['Другое основание',()=>other('Л-2Б.1.7')],['Не знаю / затрудняюсь определить',lnrP_diagnoseBasis]])}
function lnrP_inheritanceOwnerFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА НАСЛЕДНИКА','<p><b>Основание:</b> свидетельство о праве на наследство на автомобиль.</p><p>Место проживания наследника в ЛНР на 30 сентября 2022 года в этой ветке не проверяется.</p><h3>📋 Что подготовить</h3><p>Паспорт РФ; свидетельство о праве на наследство; свидетельство о регистрации транспортного средства ЛНР на имя умершего; государственные регистрационные знаки ЛНР, если сохранились; иные имеющиеся документы; автомобиль для осмотра.</p><p>При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🛑 Если отказали</h3><p>Подайте документы официально и получите письменное решение с конкретным правовым основанием.</p>')}
function lnrP_inheritanceOwner(){q('Являетесь ли вы гражданином Российской Федерации?',[['Да',lnrP_inheritanceOwnerFinal],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])}
