function lnrP_heirDisposition(){q('Как планируется оформить автомобиль дальше?',[['Зарегистрировать автомобиль на наследника',lnrP_inheritanceOwner],['Продать автомобиль нынешнему владельцу',()=>lnrP_heirParticipation(lnrP_heirSaleFinal)],['Подарить автомобиль нынешнему владельцу',()=>lnrP_heirParticipation(lnrP_heirGiftFinal)],['Другая ситуация / нет подходящего варианта',()=>other('Л-2В.2.2')]])}
function lnrP_inheritancePending(){result('yellow','🟡 НАСЛЕДСТВО ЕЩЁ НЕ ОФОРМЛЕНО','<p>Свидетельство о праве на наследство на автомобиль ещё не получено.</p><h3>⚖️ Возможны два маршрута</h3><p><b>1. Не ждать окончания оформления наследства.</b> Обратиться за регистрацией автомобиля на российский учёт на ограниченный срок 5 лет. При успешной регистрации выдаётся <b>СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ</b>. После получения свидетельства о праве на наследство можно обратиться в МРЭО для снятия ограничения и регистрации автомобиля на постоянный российский учёт.</p><p><b>2. Дождаться свидетельства о праве на наследство.</b> После его получения обратиться непосредственно за постоянной регистрацией автомобиля на российский учёт на основании наследства, без промежуточной регистрации на 5 лет.</p><h3>📋 Что выбрать</h3><p>Если автомобилем необходимо пользоваться до завершения наследственного оформления, можно использовать первый маршрут. Если временная регистрация не требуется, можно дождаться свидетельства о праве на наследство и сразу перейти к постоянной регистрации.</p><h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Подайте документы официально и получите письменное решение МРЭО с конкретным правовым основанием.</p>')}
function lnrP_inheritanceStatus(){q('Оформлено ли наследство на автомобиль?',[['Да, имеется свидетельство о праве на наследство',lnrP_heirDisposition],['Нет, наследство ещё не оформлено',lnrP_inheritancePending]])}
function lnrP_heirs(){q('Известны ли вам наследники умершего собственника и готовы ли они участвовать в оформлении автомобиля?',[['Да, наследники известны и готовы участвовать',lnrP_inheritanceStatus],['Наследники известны, но не хотят участвовать',()=>lnrP_five('Наличие наследников и их нежелание участвовать не создаёт у фактического владельца право собственности. Основание 5-летней регистрации — объяснение о реальных обстоятельствах владения.')],['Наследники неизвестны / связи с ними нет',()=>lnrP_five('Разыскивать наследников как предварительное условие этого маршрута Навигатор не требует. Пятилетняя регистрация не создаёт право собственности.')],['Наследников нет',()=>lnrP_five('Отсутствие наследников само по себе не делает фактического владельца собственником. Вопрос приобретения права собственности решается отдельно.')]])}
function lnrP_deceased(){q('Имеется ли у вас документ, подтверждающий ваше право собственности на автомобиль?',[['Свидетельство о праве на наследство, выданное на моё имя',lnrP_inheritanceOwner],['Вступившее в законную силу решение суда РФ о признании за мной права собственности',lnrP_court],['Нет, такого документа у меня нет',lnrP_heirs],['Другой документ / другая ситуация',()=>other('Л-2В.1')]])}
function lnrP_five(reason){result('yellow','🟡 Регистрация на 5 лет','<p><b>Статус:</b> владение автомобилем (не являюсь собственником по свидетельству о регистрации транспортного средства ЛНР).</p><p><b>Основание регистрации при отсутствии иного документа:</b> объяснение владельца об обстоятельствах владения автомобилем. Указывать необходимо реальные обстоятельства получения и пользования автомобилем.</p><p>'+reason+'</p><p><b>Практика:</b> если МРЭО становится известно о смерти собственника по свидетельству о регистрации транспортного средства ЛНР, возможен фактический отказ. В таком случае следует получить письменное решение с конкретным правовым основанием.</p><p class="warn"><b>⚠️ Нельзя оформлять ДКП задним числом от имени умершего, подделывать его подпись или использовать заведомо подложные документы.</b> Это может повлечь спор с наследниками, отказ в регистрации, а в зависимости от обстоятельств — уголовную ответственность.</p><p>Если наследники найдутся и готовы участвовать, возможен законный маршрут: оформление наследства → новая сделка с наследником → регистрация приобретателя при соблюдении условий специального порядка.</p>')}
function lnrOwnerFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ','<p><b>⚖️ Что предусматривает закон</b></p><p>При выполнении условий этой ветки автомобиль подпадает под специальный порядок перерегистрации на российский государственный учёт. Регистрация производится постоянно, а не на 5 лет.</p><p><b>🚘 Что получает владелец</b></p><p><b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ.</b></p><p><b>📋 Что делать</b></p><p>Обратиться в МРЭО с автомобилем и документами: паспортом РФ, свидетельством о регистрации транспортного средства ЛНР, имеющимися документами на автомобиль, регистрационными знаками ЛНР и документами, подтверждающими проживание на территории ЛНР до вступления ЛНР в состав Российской Федерации.</p><p><b>🛑 Если МРЭО отказывает</b></p><p>Не ограничивайтесь устным отказом. Представьте документы официально и получите письменное решение с указанием конкретного правового основания отказа. После этого можно определить дальнейший способ защиты.</p><p><b>📚 Нормативные основания</b></p><p>Точные реквизиты и пункты будут внесены после проверки окончательной редакции нового постановления Правительства РФ.</p>')}
function lnrProof(){q('Имеются ли у вас документы, подтверждающие проживание или регистрацию по месту жительства на территории ЛНР?',[['Да',lnrOwnerFinal],['Нет',()=>pending('Необходимо дополнительно подтвердить проживание или регистрацию по месту жительства на территории ЛНР')],['Не знаю, какие документы могут это подтвердить',()=>pending('Нужно определить документы, подтверждающие территориальную связь с ЛНР')]])}
function lnrResidence(){q('Вы проживали или были зарегистрированы по месту жительства на территории ЛНР на момент принятия ЛНР в состав Российской Федерации?',[['Да, проживал в ЛНР',lnrProof],['Да, был зарегистрирован по месту жительства в ЛНР',lnrProof],['Да, проживал в ЛНР и был зарегистрирован по месту жительства',lnrProof],['Нет, не проживал и не был зарегистрирован по месту жительства в ЛНР',()=>result('red','🔴 СПЕЦИАЛЬНЫЙ ПОРЯДОК НЕ ПРИМЕНЯЕТСЯ','<p>По выбранным ответам территориальное условие для этого маршрута не выполнено.</p><h3>🛑 Если считаете вывод неверным</h3><p>Проверьте документы и измените ответы. При фактическом отказе МРЭО получите письменное решение с указанием правового основания.</p>')]],'<p>ℹ️ ЛНР принята в состав Российской Федерации <b>30 сентября 2022 года</b>.</p>')}
function lnrCitizen(){q('Являетесь ли вы гражданином Российской Федерации?',[['Да',lnrResidence],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])}
function lnrOwner(){q('На кого оформлено свидетельство о регистрации транспортного средства ЛНР?',[['На меня',lnrP_citizen],['На другого человека',lnrP_ownerBasis],['На умершего собственника',lnrP_deceased],['Другая ситуация / нет подходящего варианта',()=>other('Л-2')]])}

function limpArticle(){return '<p><b>📖 Подробнее:</b> <a href="https://rk-avtopravo.ru/kak-podtverdit-registraciyu-avtomobilya-lnr/" target="_blank" rel="noopener">Как подтвердить прежнюю регистрацию автомобиля в ЛНР</a>.</p>'}
function limpMainArticle(){return '<p><b>📖 Подробнее:</b> <a href="https://rk-avtopravo.ru/avto-iz-za-rubezha-v-lnr-registraciya-rf/" target="_blank" rel="noopener">Автомобили, ввезённые из-за рубежа в ЛНР: регистрация на российский учёт</a>.</p>'}
function limpOwnerFivePlus(){result('yellow','🟡 ДВА РАВНОЗНАЧНЫХ МАРШРУТА','<p>Вы являетесь <b>Владельцем 1</b>, а с момента первой временной регистрации автомобиля в ЛНР на ваше имя прошло 5 лет или более.</p><h3>1. Регистрация на российский учёт на 5 лет</h3><p>Можно использовать маршрут временной регистрации автомобиля на российский государственный учёт на 5 лет. При успешной регистрации выдаются <b>СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ</b>. Такая регистрация сама по себе не означает признания права собственности на автомобиль.</p><h3>2. Приобретательная давность</h3><p>Можно отдельно рассмотреть обращение в суд с требованием о признании права собственности по приобретательной давности. Для оценки пятилетнего периода в этой ветке учитывается срок с <b>первой временной регистрации автомобиля в ЛНР на ваше имя</b>, а не только дата последнего свидетельства.</p><p><b>Важно:</b> истечение пяти лет само по себе не означает автоматического возникновения права собственности. Для судебного маршрута необходимо оценить и остальные предусмотренные законом условия приобретательной давности.</p><h3>📋 Если история регистрации подтверждена не полностью</h3><p>Запросите в МРЭО сведения обо всей последовательности временных регистраций. Если получить необходимые сведения самостоятельно не удаётся и дело уже рассматривается судом, можно просить суд истребовать их.</p>'+limpMainArticle()+'<p><b>📖 Приобретательная давность:</b> <a href="https://rk-avtopravo.ru/pravo-sobstvennosti-na-avtomobil-v-novih-regionah/" target="_blank" rel="noopener">Право собственности на автомобиль в новых регионах</a>.</p><h3>🛑 Если МРЭО отказало в регистрации на 5 лет</h3><p>Не ограничивайтесь устным отказом. Подайте документы официально и получите письменное решение с конкретным правовым основанием. После этого можно оценивать административное обжалование и обращение в суд.</p>')}
function limpOwnerUnderFive(){result('yellow','🟡 РЕГИСТРАЦИЯ РФ НА 5 ЛЕТ','<p>Вы являетесь <b>Владельцем 1</b>, но с момента первой временной регистрации автомобиля в ЛНР на ваше имя ещё не прошло 5 лет.</p><h3>⚖️ Что предусматривает маршрут</h3><p>На данном этапе Навигатор предлагает маршрут временной регистрации автомобиля на российский государственный учёт на 5 лет. При успешной регистрации выдаются <b>СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ</b>. Такая регистрация сама по себе не означает признания права собственности.</p><p>Судебный маршрут по приобретательной давности на основании пятилетнего срока в этой ветке пока не предлагается.</p>'+limpMainArticle()+'<h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Подайте документы официально и получите письменное решение с конкретным правовым основанием. После этого можно оценивать административное обжалование и обращение в суд.</p>')}
function limpFirstDate(){q('Когда автомобиль впервые был поставлен на временный регистрационный учёт ЛНР на ваше имя?',[['Первая временная регистрация ЛНР была оформлена 5 лет назад или ранее',limpOwnerFivePlus],['С момента первой временной регистрации прошло менее 5 лет',limpOwnerUnderFive],['Не знаю дату первой временной регистрации',()=>result('yellow','🟡 НУЖНО УСТАНОВИТЬ ИСТОРИЮ РЕГИСТРАЦИИ','<p>Если свидетельство временной регистрации ЛНР менялось ежегодно, для дальнейшей оценки важна <b>первая временная регистрация автомобиля на ваше имя</b>, а не дата последнего свидетельства.</p><h3>📋 Что делать</h3><p>Запросите в МРЭО сведения об истории временной регистрации автомобиля. Если необходимые сведения самостоятельно получить не удаётся и вопрос рассматривается судом, можно заявить ходатайство об истребовании соответствующих сведений судом.</p>'+limpMainArticle()+'<h3>🛑 Если отказали в предоставлении сведений</h3><p>Получите письменный ответ или отказ и оцените его обжалование.</p>')]],'<p>ℹ️ Если свидетельство временной регистрации ЛНР выдавалось неоднократно, ориентируйтесь на <b>первую временную регистрацию автомобиля на ваше имя</b>, а не на дату последнего выданного свидетельства.</p>')}
function limpDeadOwner2Final(extra=''){result('yellow','🟡 РЕГИСТРАЦИЯ НА ВЛАДЕЛЬЦА 2 НА РОССИЙСКИЙ УЧЁТ НА 5 ЛЕТ','<p>Временная регистрация ЛНР была оформлена на <b>Владельца 1, который умер</b>, а автомобиль фактически находится у вас — <b>Владельца 2</b>.</p>'+extra+'<h3>⚖️ Что предусматривает маршрут</h3><p>По принятой в Навигаторе логике смерть Владельца 1 сама по себе не исключает обращение Владельца 2 за временной регистрацией автомобиля на российский государственный учёт на 5 лет. При успешной регистрации выдаются <b>СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ</b>. Такая регистрация сама по себе не означает признания права собственности.</p><h3>📋 Что делать</h3><p>Подайте документы в МРЭО официально, представьте имеющиеся документы на автомобиль и автомобиль на осмотр. Обстоятельства поступления автомобиля во владение указывайте такими, какими они были в действительности.</p><p>Если документы временной регистрации ЛНР, оформленные на умершего Владельца 1, отсутствуют, Навигатор не предлагает Владельцу 2 восстанавливать их от имени умершего. Используются имеющиеся документы и иные допустимые сведения об истории автомобиля.</p><h3>🚘 Как может быть на практике</h3><p>В этой ситуации возможен отказ МРЭО, особенно если временная регистрация оформлялась на умершего Владельца 1 и подтверждающих документов недостаточно. Практический отказ не приравниваем к автоматическому отсутствию пятилетнего маршрута.</p><h3>📖 Подробнее</h3><p><a href="https://rk-avtopravo.ru/registraciya-avto-na-vladelca-2-sts-dnr-lnr/" target="_blank" rel="noopener">Регистрация автомобиля на Владельца 2 со свидетельством ДНР/ЛНР</a></p>'+limpMainArticle()+'<h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Потребуйте принять документы и выдать письменное решение с конкретным правовым основанием. После получения решения необходимо отдельно оценить основания для административного обжалования или обращения в суд.</p><h3>⚠️ Приобретательная давность</h3><p>Навигатор не делает автоматический вывод о присоединении периода владения умершего Владельца 1 к периоду Владельца 2. Этот вопрос оставлен для отдельной правовой оценки.</p>')}
function limpDeadOwnerDocs(){q('Сохранились ли документы временной регистрации ЛНР, оформленные на умершего Владельца 1?',[['Да, документы сохранились',()=>limpDeadOwner2Final('<p><b>Документы:</b> сохранились документы временной регистрации ЛНР, оформленные на умершего Владельца 1.</p>')],['Нет, документы были изъяты в МРЭО или утрачены',limpDeadOwnerUkraineDocs],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.2В.2')]],'<p>ℹ️ Если документы временной регистрации умершего Владельца 1 отсутствуют, Владелец 2 не направляется Навигатором на восстановление этих документов от своего имени. Далее проверяем дополнительные документы, которыми можно подтвердить историю автомобиля.</p>')}
function limpDeadOwnerUkraineDocs(){q('Сохранились ли украинские регистрационные документы на автомобиль?',[['Да, сохранились',()=>limpDeadOwner2Final('<p><b>Документы:</b> документы временной регистрации ЛНР отсутствуют, но сохранились украинские регистрационные документы. Они могут дополнительно подтверждать историю автомобиля.</p>')],['Нет, украинских регистрационных документов нет',()=>limpDeadOwner2Final('<p><b>Документы:</b> документы временной регистрации ЛНР и украинские регистрационные документы отсутствуют. Это не используется Навигатором как автоматический запрет пятилетнего маршрута, но существенно повышает доказательственную сложность.</p>')],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.2В.3')]],'<p>ℹ️ Наличие украинских регистрационных документов может упростить подтверждение истории автомобиля. Их отсутствие само по себе не используется как автоматический запрет пятилетней регистрации.</p>')}
function limpDeadHolder(){q('Временная регистрация ЛНР была оформлена на Владельца 1, который умер. Автомобиль сейчас фактически находится у вас?',[['Да, автомобиль фактически находится у меня — я Владелец 2',limpDeadOwnerDocs],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.2В.1')]],'<p>ℹ️ В этой ветке не рассматриваем наследование автомобиля. Навигатор определяет дальнейший маршрут для фактического Владельца 2 после смерти лица, на которое была оформлена временная регистрация ЛНР.</p>')}
function limpOwner2Final(extra=''){result('yellow','🟡 РЕГИСТРАЦИЯ АВТОМОБИЛЯ НА ВЛАДЕЛЬЦА 2 НА РОССИЙСКИЙ УЧЁТ НА 5 ЛЕТ','<p>Во временном свидетельстве о регистрации ЛНР указан <b>Владелец 1</b>, а автомобилем фактически владеете вы — <b>Владелец 2</b>.</p>'+extra+'<h3>⚖️ Что предусматривает маршрут</h3><p>По принятой в Навигаторе логике Владелец 2 может обратиться за временной регистрацией автомобиля на российский государственный учёт на 5 лет на своё имя. При успешной регистрации выдаются <b>СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ</b>. Такая регистрация сама по себе не означает признания права собственности на автомобиль.</p><h3>📋 Что делать</h3><p>Подготовьте сохранившееся свидетельство временной регистрации ЛНР либо официальное подтверждение прежней временной регистрации, имеющиеся регистрационные документы на автомобиль и представьте автомобиль на осмотр. Обстоятельства фактического владения указывайте такими, какими они были в действительности.</p><p>ДКП, договор дарения, доверенность или расписка между Владельцем 1 и Владельцем 2 в этой ветке не рассматриваются как основание перехода права собственности на автомобиль.</p><h3>🚘 Как может быть на практике</h3><p>По известной нам практике МРЭО в подобных ситуациях нередко отказывает Владельцу 2 из-за того, что прежняя временная регистрация оформлена на другое лицо. Практический отказ не приравниваем к отсутствию самого маршрута: документы следует подать официально и потребовать письменное решение.</p><h3>📖 Подробнее о регистрации на Владельца 2</h3><p><a href="https://rk-avtopravo.ru/registraciya-avto-na-vladelca-2-sts-dnr-lnr/" target="_blank" rel="noopener">Регистрация автомобиля на Владельца 2 со свидетельством ДНР/ЛНР</a></p>'+limpMainArticle()+'<h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Получите письменное решение МРЭО с конкретным правовым основанием, проанализируйте его и при наличии оснований обжалуйте административно либо в суде.</p><h3>⚠️ Приобретательная давность</h3><p>Навигатор пока не присоединяет автоматически период владения Владельца 1 к периоду Владельца 2 для вывода о приобретательной давности. Этот вопрос требует отдельной правовой оценки.</p>')}
function limpOwner2Docs(){q('Сохранился ли документ, подтверждающий временную регистрацию автомобиля в ЛНР на Владельца 1?',[['Да, временное свидетельство ЛНР сохранилось',limpOwner2Final],['Свидетельство было изъято, но имеется справка или письменное подтверждение МРЭО',limpOwner2Final],['Документ утрачен или изъят, подтверждения нет, но с Владельцем 1 можно связаться',()=>result('yellow','🟡 НУЖНО ПОДТВЕРДИТЬ ПРЕЖНЮЮ РЕГИСТРАЦИЮ','<p>Получить официальное подтверждение прежней временной регистрации может <b>Владелец 1</b> — лицо, на которое была оформлена временная регистрация ЛНР.</p><p>После подтверждения регистрации можно продолжить маршрут регистрации автомобиля на Владельца 2 на российский учёт на 5 лет.</p>'+limpArticle()+'<h3>🛑 Если МРЭО отказывает Владельцу 1</h3><p>Нужно получить письменный ответ с конкретным основанием отказа и оценить его обжалование.</p>')],['Документов или подтверждения нет и связаться с Владельцем 1 невозможно',limpOwner2UkraineDocs],['Владелец 1 умер',limpDeadHolder],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.2Б.1')]],'<p>В этой ветке не используем ДКП, договор дарения, доверенность или расписку между Владельцем 1 и Владельцем 2 как основание перехода права собственности.</p>')}
function limpOwner2UkraineDocs(){q('Сохранились ли украинские регистрационные документы на автомобиль?',[['Да, сохранились',()=>limpOwner2Final('<p><b>Дополнительное обстоятельство:</b> украинские регистрационные документы сохранились и могут дополнительно подтверждать историю автомобиля.</p>')],['Нет, украинских регистрационных документов нет',()=>limpOwner2Final('<p><b>Дополнительное обстоятельство:</b> украинские регистрационные документы отсутствуют. Это само по себе не исключает пятилетний маршрут, но может усложнить доказывание истории автомобиля и увеличить риск отказа МРЭО.</p>')],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.2Б.2')]],'<p>ℹ️ Украинские регистрационные документы могут упростить подтверждение истории автомобиля. Их отсутствие само по себе не означает невозможность регистрации на российский учёт на 5 лет.</p>')}
function limpHolder(){q('На кого была оформлена временная регистрация автомобиля в ЛНР?',[['На меня — я Владелец 1',limpFirstDate],['На другого человека — я Владелец 2',limpOwner2Docs],['Владелец 1 умер',limpDeadHolder],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.2')]],'<p>Смотрите свидетельство о временной регистрации ЛНР либо официальный документ МРЭО, подтверждающий такую регистрацию.</p>')}
function limpConfirm(){q('Имеется ли документ, подтверждающий прежнюю временную регистрацию автомобиля в ЛНР?',[['Да, имеется справка или письменный ответ МРЭО',limpHolder],['Нет, письменно в МРЭО ещё не обращался',()=>result('yellow','🟡 СНАЧАЛА ПОДТВЕРДИТЕ ПРЕЖНЮЮ РЕГИСТРАЦИЮ','<p>Обратитесь в МРЭО письменно за сведениями о прежней временной регистрации автомобиля в ЛНР.</p>'+limpArticle()+'<h3>🛑 Если отказали</h3><p>Получите письменный ответ с основанием отказа. После этого можно определить дальнейший способ защиты.</p>')],['Обращался письменно, но МРЭО отказало',()=>result('yellow','🟡 ПОЛУЧЕН ОТКАЗ МРЭО','<p>Письменный отказ необходимо анализировать по указанному в нём правовому основанию и при наличии оснований обжаловать.</p>'+limpArticle()+'<h3>🛑 Что делать</h3><p>Сохраните заявление и письменный ответ МРЭО. Не ограничивайтесь устными пояснениями сотрудников.</p>')],['В МРЭО сообщили, что сведений о регистрации нет / база отсутствует',()=>result('yellow','🟡 ТРЕБУЕТСЯ ДОПОЛНИТЕЛЬНОЕ ДОКАЗЫВАНИЕ','<p>Отсутствие сведений в имеющейся базе само по себе не используется Навигатором как автоматический вывод о том, что временной регистрации ЛНР не было.</p>'+limpArticle()+'<h3>🛑 Что делать</h3><p>Получите официальный письменный ответ МРЭО и определите дальнейший доказательственный маршрут.</p>')],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.1.1')]])}
function limpDocs(){q('Изымались ли в МРЭО документы временной регистрации ЛНР?',[['Нет, документы временной регистрации ЛНР сохранились',limpHolder],['Да, документы были изъяты в МРЭО',limpConfirm],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.1')]],'<p>ℹ️ Речь именно о <b>свидетельстве временной регистрации ЛНР</b>. Наличие регистрационных знаков ЛНР само по себе в этой ветке не рассматривается как достаточное подтверждение прежней регистрации.</p>')}

function lnrD1(){q('Какая регистрация указана в документах ЛНР?',[['Постоянная регистрация ЛНР',lnrOwner],['Временная регистрация ЛНР на 5 лет (автомобиль не ввозился из-за рубежа до вхождения ЛНР в состав РФ)',tempLnr],['Временная регистрация ЛНР автомобиля, ввезённого из-за рубежа до вхождения ЛНР в состав РФ',limpDocs],['Другая ситуация / нет подходящего варианта',()=>other('Л-1')]])}

function start(){hist=[];q('На каком учёте находится автомобиль?',[['ДНР',d1],['ЛНР',lnrD1],['Украина (кроме Херсонской и Запорожской областей)',()=>pending('Украина')],['Запорожская область',()=>pending('Запорожская область')],['Херсонская область',()=>pending('Херсонская область')],['Другая ситуация',()=>q('Какая именно ситуация?',[['Растаможен на Украине, но не был зарегистрирован',()=>pending('Растаможен на Украине, но не зарегистрирован')],['Транзитные номера Украины',()=>pending('Транзитные номера Украины')],['Снят с регистрационного учёта',()=>pending('Снят с регистрационного учёта')],['Регистрационные документы утрачены',()=>pending('Документы утрачены')],['Автомобиль никогда не был зарегистрирован',()=>pending('Никогда не был зарегистрирован')],['Иностранный учёт другого государства',()=>pending('Иностранный учёт')],['Другая ситуация / не знаю, что выбрать',()=>other('ДР-1.7')]])]],'Выберите не регион, где автомобиль находится сейчас, а регистрационный учёт по имеющимся документам и государственным номерам.')}start();